-- New diary entries are generated by the /diary Claude skill (template: ~/vimwiki/templates/diary.md).
-- The job runs async: a placeholder line is inserted, then swapped for the entry when claude finishes.
local PLACEHOLDER = "<!-- generating diary entry... -->"

local FALLBACK = {
  "## Writing Prompt",
  "",
  "# Important Tasks",
  "",
  "# Projects",
  "",
  "-----",
  "",
  "## Meetings",
  "",
  "-----",
  "",
  "## Notes",
  "",
}

local function replace_placeholder(buf, lines)
  if not vim.api.nvim_buf_is_valid(buf) then
    return
  end
  for i, line in ipairs(vim.api.nvim_buf_get_lines(buf, 0, -1, false)) do
    if line == PLACEHOLDER then
      vim.api.nvim_buf_set_lines(buf, i - 1, i, false, lines)
      return
    end
  end
end

vim.api.nvim_create_autocmd("BufNewFile", {
  pattern = vim.fn.expand("~") .. "/vimwiki/diary/*.md",
  callback = function(args)
    local date = vim.fn.fnamemodify(args.file, ":t:r")
    if not date:match("^%d%d%d%d%-%d%d%-%d%d$") then
      return
    end

    local buf = args.buf
    vim.api.nvim_buf_set_lines(buf, 0, 0, false, { PLACEHOLDER })

    vim.system(
      { "claude", "-p", "/diary " .. date },
      { cwd = vim.fn.expand("~/vimwiki"), text = true, timeout = 120000, stdin = "" },
      vim.schedule_wrap(function(result)
        local out = vim.trim(result.stdout or "")
        if result.code == 0 and out:find("# Important Tasks", 1, true) then
          replace_placeholder(buf, vim.split(out, "\n"))
        else
          local reason = result.code == 124 and "timed out" or ("exit " .. result.code)
          local lines = { "<!-- diary generation failed (" .. reason .. ") -->" }
          vim.list_extend(lines, FALLBACK)
          replace_placeholder(buf, lines)
        end
      end)
    )
  end,
})

-- Saving a diary entry completes its checked, text-matched tasks in todo.sh (no Claude, no confirmation).
-- Anything uncertain is left for a manual /diary-sync.
vim.api.nvim_create_autocmd("BufWritePost", {
  pattern = vim.fn.expand("~") .. "/vimwiki/diary/*.md",
  callback = function(args)
    local date = vim.fn.fnamemodify(args.file, ":t:r")
    if not date:match("^%d%d%d%d%-%d%d%-%d%d$") then
      return
    end

    vim.system(
      { vim.fn.expand("~/.claude/skills/diary-sync/apply-done.rb"), args.file },
      { text = true, timeout = 30000 },
      vim.schedule_wrap(function(result)
        local completed, review = (result.stdout or ""):match("completed=(%d+) review=(%d+)")
        if not completed then
          return
        end
        if tonumber(completed) > 0 then
          vim.notify("diary-sync: completed " .. completed .. " task(s) in todo.sh")
        end
        if tonumber(review) > 0 then
          vim.notify("diary-sync: " .. review .. " item(s) need review, run /diary-sync")
        end
      end)
    )
  end,
})
